fn hash(p:impl AsRef<Path>)->String{let p=p.as_ref();let mut f=match fs::File::open(p){Ok(f)=>f,Err(e)if e.kind()==std::io::ErrorKind::PermissionDenied&&p.file_name().is_some_and(|x|x=="perf.data")=>{let o=Command::new("sudo").args(["-n","sha256sum"]).arg(p).output().unwrap();assert!(o.status.success());return String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap().into();},Err(e)=>panic!("{}:{e}",p.display())};let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
